"use client";

import { useState } from "react";
import { zodResolver } from "@hookform/resolvers/zod";
import { useForm } from "react-hook-form";
import { z } from "zod";
import { ArrowDown, Clock3, Pencil, Plus, Power, Route, Trash2 } from "lucide-react";
import { toast } from "sonner";
import type { MessageTemplate, Sequence, SequenceStep } from "@/types/chatbot";
import { Badge } from "@/components/ui/badge";
import { Button } from "@/components/ui/button";
import { Dialog, DialogContent, DialogDescription, DialogHeader, DialogTitle } from "@/components/ui/dialog";
import { Input } from "@/components/ui/input";
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from "@/components/ui/select";
import { chatbotChannelSchema, firstSchemaError, sequenceFormSchema, sequenceSchema } from "@/services/chatbot/schemas";

interface Props { sequences: Sequence[]; templates: MessageTemplate[]; isBusy: boolean; onSave: (sequence: Sequence) => Promise<void> }

export function SequencesWorkspace({ sequences, templates, isBusy, onSave }: Props) {
  const [editing, setEditing] = useState<Sequence | null>(null); const [draft, setDraft] = useState<Sequence | null>(null);
  const active = editing ?? draft;
  async function persist(sequence: Sequence) { const parsed = sequenceSchema.safeParse(sequence); if (!parsed.success) { toast.error(firstSchemaError(parsed)); return false; } try { await onSave(parsed.data); toast.success("Sequência atualizada sem executar envios"); return true; } catch (error) { toast.error(error instanceof Error ? error.message : "Não foi possível salvar a sequência."); return false; } }
  function addStep() { if (!active) return; if (!templates[0]) { toast.error("Crie um template antes de adicionar passos."); return; } const step: SequenceStep = { id: `step-${Date.now()}`, order: active.steps.length + 1, delay: "1 dia", templateId: templates[0].id, channel: "whatsapp" }; const next = { ...active, steps: [...active.steps, step] }; if (editing) setEditing(next); else setDraft(next); }
  function updateStep(id: string, patch: Partial<SequenceStep>) { if (!active) return; const next = { ...active, steps: active.steps.map((step) => step.id === id ? { ...step, ...patch } : step) }; if (editing) setEditing(next); else setDraft(next); }
  function removeStep(id: string) { if (!active) return; const steps = active.steps.filter((step) => step.id !== id).map((step, index) => ({ ...step, order: index + 1 })); const next = { ...active, steps }; if (editing) setEditing(next); else setDraft(next); }
  return <div className="space-y-4 p-4 md:p-5" data-testid="chatbot-sequences"><header className="flex items-center justify-between"><div><h2 className="text-lg font-semibold text-white">Sequências</h2><p className="text-sm text-slate-400">Cadências visuais com passos, espera e canal.</p></div><Button disabled={isBusy} onClick={() => setDraft(emptySequence(sequences.length + 1))}><Plus className="mr-2 size-4" />Nova sequência</Button></header>
    <div className="grid gap-3 lg:grid-cols-2">{sequences.map((sequence) => <article key={sequence.id} className="rounded-xl border border-white/10 bg-slate-950/60 p-4"><div className="flex items-start justify-between"><div className="flex gap-3"><div className="grid size-10 place-items-center rounded-lg bg-cyan-400/10 text-cyan-300"><Route className="size-5" /></div><div><h3 className="font-semibold text-white">{sequence.name}</h3><p className="mt-1 text-sm text-slate-400">{sequence.description}</p></div></div><Badge className={sequence.status === "active" ? "bg-emerald-400/10 text-emerald-300" : "bg-slate-700 text-slate-300"}>{sequence.status}</Badge></div>
      <div className="mt-4 space-y-1">{sequence.steps.map((step, index) => <div key={step.id}>{index > 0 && <ArrowDown className="mx-auto size-4 text-slate-600" />}<div className="flex items-center justify-between rounded-lg bg-white/[0.03] p-2.5 text-xs"><span className="text-slate-300"><strong className="mr-2 text-indigo-300">{step.order}</strong>{templates.find((item) => item.id === step.templateId)?.name || "Template"}</span><span className="flex items-center gap-1 capitalize text-slate-500"><Clock3 className="size-3" />{step.delay} · {step.channel}</span></div></div>)}</div>
      <footer className="mt-4 flex items-center justify-between text-xs text-slate-500"><span>{sequence.contacts} contatos · {sequence.steps.length} passos</span><div className="flex gap-2"><Button variant="outline" size="sm" disabled={isBusy} onClick={() => { void persist({ ...sequence, status: sequence.status === "active" ? "paused" : "active" }); }}><Power className="mr-1 size-3.5" />{sequence.status === "active" ? "Pausar" : "Ativar"}</Button><Button size="sm" disabled={isBusy} onClick={() => setEditing(sequence)}><Pencil className="mr-1 size-3.5" />Editar</Button></div></footer>
    </article>)}</div>
    <Dialog open={Boolean(active)} onOpenChange={(open) => { if (!open && !isBusy) { setEditing(null); setDraft(null); } }}><DialogContent className="max-h-[92vh] overflow-y-auto border-white/10 bg-slate-950 text-white sm:max-w-3xl"><DialogHeader><DialogTitle>{draft ? "Nova sequência" : "Editar sequência"}</DialogTitle><DialogDescription className="text-slate-400">Passos são armazenados somente na memória do mock.</DialogDescription></DialogHeader>{active && <SequenceFormPanel key={active.id} sequence={active} templates={templates} isBusy={isBusy} onAddStep={addStep} onUpdateStep={updateStep} onRemoveStep={removeStep} onSave={async (values) => { const saved = await persist({ ...active, ...values, updatedAt: new Date().toISOString() }); if (saved) { setEditing(null); setDraft(null); } }} />}</DialogContent></Dialog>
  </div>;
}
type SequenceForm = z.infer<typeof sequenceFormSchema>;
function SequenceFormPanel({ sequence, templates, isBusy, onAddStep, onUpdateStep, onRemoveStep, onSave }: { sequence: Sequence; templates: MessageTemplate[]; isBusy: boolean; onAddStep: () => void; onUpdateStep: (id: string, patch: Partial<SequenceStep>) => void; onRemoveStep: (id: string) => void; onSave: (values: SequenceForm) => Promise<void> }) {
  const { register, handleSubmit, formState: { errors } } = useForm<SequenceForm>({ resolver: zodResolver(sequenceFormSchema), defaultValues: { name: sequence.name, description: sequence.description } });
  return <form onSubmit={handleSubmit(onSave)} aria-busy={isBusy} className="space-y-3"><Field error={errors.name?.message}><Input {...register("name")} disabled={isBusy} maxLength={120} placeholder="Nome da sequência" aria-invalid={Boolean(errors.name)} /></Field><Field error={errors.description?.message}><Input {...register("description")} disabled={isBusy} maxLength={500} placeholder="Descrição" aria-invalid={Boolean(errors.description)} /></Field><div className="space-y-2">{sequence.steps.map((step) => <div key={step.id} className="grid gap-2 rounded-lg border border-white/10 bg-white/[0.025] p-3 sm:grid-cols-[42px_1fr_120px_130px_36px]"><div className="grid place-items-center text-sm font-semibold text-indigo-300">#{step.order}</div><Select disabled={isBusy} value={step.templateId} onValueChange={(value) => onUpdateStep(step.id, { templateId: value })}><SelectTrigger><SelectValue /></SelectTrigger><SelectContent>{templates.map((template) => <SelectItem key={template.id} value={template.id}>{template.name}</SelectItem>)}</SelectContent></Select><Input disabled={isBusy} value={step.delay} maxLength={60} onChange={(e) => onUpdateStep(step.id, { delay: e.target.value })} aria-label={`Espera do passo ${step.order}`} /><Select disabled={isBusy} value={step.channel} onValueChange={(value) => { const parsed = chatbotChannelSchema.safeParse(value); if (parsed.success) onUpdateStep(step.id, { channel: parsed.data }); }}><SelectTrigger><SelectValue /></SelectTrigger><SelectContent>{["whatsapp", "instagram", "messenger", "telegram", "email", "webchat"].map((channel) => <SelectItem key={channel} value={channel}>{channel}</SelectItem>)}</SelectContent></Select><Button type="button" variant="ghost" size="icon" disabled={isBusy} onClick={() => onRemoveStep(step.id)} aria-label={`Remover passo ${step.order}`}><Trash2 className="size-4 text-red-300" /></Button></div>)}</div><Button type="button" variant="outline" disabled={isBusy} onClick={onAddStep}><Plus className="mr-2 size-4" />Adicionar passo</Button><div className="flex justify-end"><Button type="submit" disabled={isBusy || !sequence.steps.length}>{isBusy ? "Salvando…" : "Salvar sequência"}</Button></div></form>;
}
function Field({ error, children }: { error?: string; children: React.ReactNode }) { return <label className="block">{children}{error && <span role="alert" className="mt-1 block text-xs text-rose-300">{error}</span>}</label>; }
function emptySequence(number: number): Sequence { return { id: `sequence-new-${number}`, name: "", description: "", status: "draft", contacts: 0, steps: [], updatedAt: new Date().toISOString() }; }
